        dh = f.d_hb_inv(n)
        return GA.add(f.d_Omega(n), GA.neg(wedge(NI, dh)), GA.scal(c, wedge(N0, dh)))

    out = {}
    for m in range(4):
        for n in range(4):
            t1 = dOT(n) if m == 0 else {}
            t2 = dOT(m) if n == 0 else {}
            out[(m, n)] = GA.add(t1, GA.neg(t2), comm(f.omega_T(m, P), f.omega_T(n, P)))
    return out


