    I, V = pair(lam)
    a, b = GA.add(E[1], GA.scal(F(2), E[0])), GA.add(GA.sub(NI, GA.scal(lam / 6, N0)), E[2])
    ok = dot(a, I) == 0 and dot(b, I) == 0 and dot(a, a) != 0 and dot(b, b) != 0
    R = mul(a, b)
